/* Version and relative file lists are generated by tools/package.py. */
importScripts('./precache.js');

const scope = self.registration.scope;
const prefix = 'cermat-cz:' + new URL(scope).pathname + ':';
const shellCache = prefix + 'shell:' + self.CERMAT_RELEASE.version;
const archiveCache = prefix + 'archive:' + self.CERMAT_RELEASE.archiveVersion;
const core = new Set(self.CERMAT_RELEASE.core.map(path=>new URL(path,scope).href));
const archive = new Set(self.CERMAT_RELEASE.archive.map(path=>new URL(path,scope).href));
const indexUrl = new URL('./index.html',scope).href;

self.addEventListener('install', event => {
  event.waitUntil((async()=>{
    const cache=await caches.open(shellCache);
    const paths=[...core];
    for(let offset=0;offset<paths.length;offset+=18) {
      await cache.addAll(paths.slice(offset,offset+18).map(path=>new Request(path,{cache:'reload'})));
    }
    await self.skipWaiting();
  })());
});
self.addEventListener('activate',event=>{
  event.waitUntil((async()=>{
    const old=(await caches.keys()).filter(name=>name.startsWith(prefix)&&name!==shellCache&&name!==archiveCache);
    await Promise.all(old.map(name=>caches.delete(name)));
    await self.clients.claim();
  })());
});
async function asset(url,request,name) {
  const cache=await caches.open(name);
  const cached=await cache.match(url);
  if(cached)return cached;
  try{
    const response=await fetch(request);
    if(response.ok && response.status===200) await cache.put(url,response.clone()).catch(()=>{});
    return response;
  }catch{
    return new Response('Dokument není uložený offline.',{status:503,headers:{'Content-Type':'text/plain; charset=utf-8'}});
  }
}
self.addEventListener('fetch',event=>{
  if(event.request.method!=='GET')return;
  const url=new URL(event.request.url);
  if(!url.href.startsWith(scope))return;
  url.search='';
  if(event.request.mode==='navigate'&&(url.href===scope||url.href===indexUrl)){
    event.respondWith(asset(indexUrl,new Request(indexUrl),shellCache));
  }else if(core.has(url.href)){
    event.respondWith(asset(url.href,event.request,shellCache));
  }else if(archive.has(url.href)){
    // A range response cannot replace a complete PDF. A cached full PDF is valid for the viewer.
    event.respondWith(asset(url.href,new Request(url.href),archiveCache));
  }
});
let transfer;
self.addEventListener('message',event=>{
  const port=event.ports[0];
  if(!port)return;
  const type=event.data?.type;
  if(type!=='archive-status'&&type!=='cache-archive')return;
  event.waitUntil((async()=>{
    const cache=await caches.open(archiveCache);
    const cached=new Set((await cache.keys()).map(request=>request.url));
    let done=[...archive].filter(url=>cached.has(url)).length;
    if(type==='archive-status'){port.postMessage({done,total:archive.size,complete:true});return;}
    if(transfer){await transfer;done=(await cache.keys()).length;port.postMessage({done,total:archive.size,complete:true,failed:done<archive.size});return;}
    let failures=0;
    const missing=[...archive].filter(url=>!cached.has(url));
    transfer=(async()=>{
      for(let start=0;start<missing.length;start+=4){
        await Promise.all(missing.slice(start,start+4).map(async url=>{
          try {
            const response=await fetch(url);
            if(!response.ok || response.status!==200)throw new Error('Stažení selhalo');
            await cache.put(url,response);done++;
          } catch {failures++;}
        }));
        port.postMessage({done,total:archive.size});
      }
    })();
    try{await transfer;}finally{transfer=null;port.postMessage({done,total:archive.size,complete:true,failed:failures});}
  })());
});
